R=Path(__file__).resolve().parents[2];data=json.loads((R/'data/americas.json').read_text());c=json.loads((R/'research/americas-coverage.json').read_text());new=[];rr={};nn={};held={}
def a(y,n,d,t,s,st,sol,why):
 rr.setdefault(y,{})[str(n)]=d;nn.setdefault(y,{})[str(n)]=why
 if not 4<=d<=7:return
 new.append(dict(id=f'ca-cmo-{y}-{n}',country='Canada',competition='CMO',year=y,section='Part B' if y==1974 else 'National final',number=str(n),statement=st,solution=sol,sourceUrl=f'https://cms.math.ca/wp-content/uploads/2019/07/exam{y}.pdf',solutionKind='original-exposition',topic=t,tags=s,subtopics=s,difficulty=d,ratingReason=why,reviewStatus='individually-assessed',notes='Statement restated in original wording. Official CMS paper checked; original independent proof supplied because no worked solution is linked in the official archive.'))
def low(y,n,d,why):a(y,n,d,'Algebra',[],None,None,why)
def hold(y,n,why):held.setdefault(y,{})[str(n)]=why
hold(1969,1,'Published assumptions do not ensure that the denominator is nonzero: take all a_i=b_i=1 and (p_1,p_2,p_3)=(1,−1,0). The displayed ratio is then 0/0. Held rather than silently adding a hypothesis.')
low(1969,2,1.5,'Rationalize both differences. The second denominator is smaller, so the second difference is larger.')
low(1969,3,2,'Use (a+b)²≤2(a²+b²)=2c²; equality is a=b.')
low(1969,4,2.5,'Decompose the equilateral triangle into three triangles with common side length to obtain the altitude as the sum of distances.')
low(1969,5,3,'Use the angle bisector theorem to divide the opposite side, then compare areas using sin(C/2) and sin C.')
low(1969,6,2,'Each term k·k! equals (k+1)!−k!, giving (n+1)!−1.')
low(1969,7,2,'Squares modulo 8 are 0,1,4; no sum of two is 6.')
a(1969,8,4.5,'Algebra',['Functional equations','Functions & graphs'],r'An integer-valued function on the positive integers is strictly increasing, satisfies $f(mn)=f(m)f(n)$, and has $f(2)=2$. Prove $f(n)=n$ for every positive integer.',r'Multiplicativity gives $f(1)=1$, and strict increase through integer values gives $f(n)\ge n$. Suppose $f(n)>n$. Choose $k$ with $(f(n)/n)^k>2$, and choose a power of two satisfying $n^k\le2^m<2n^k$. Then monotonicity and multiplicativity give $f(n)^k=f(n^k)\le f(2^m)=2^m<2n^k$, a contradiction. Thus equality holds everywhere.','Strict integer monotonicity supplies the lower bound; comparing large powers of a hypothetical exceptional value with adjacent powers of two supplies the nontrivial upper bound.')
low(1969,9,2.5,'One of the four central gaps is at most 90 degrees, so its chord is at most √2.')
a(1969,10,4,'Geometry',['Coordinates & vectors','Geometric inequalities'],r'A right isosceles triangle has legs of length $1$. From a point on its hypotenuse, draw perpendiculars to the legs. They partition the triangle into two triangles and a rectangle. Prove that at least one of these three regions has area at least $2/9$.',r'Put the vertices at $(0,0),(1,0),(0,1)$ and the moving point at $(t,1-t)$, with $0\le t\le1$. The three areas are $t^2/2$, $(1-t)^2/2$, and $t(1-t)$. If $t\ge2/3$ the first is at least $2/9$; if $t\le1/3$ the second is. In the remaining interval, $t(1-t)\ge2/9$. Equality in the maximum occurs at $t=1/3$ and $2/3$.','The three competing area expressions require splitting the interval at the two sharp transition points, rather than applying a single average bound.')
for n,d,why in [(1,3.5,'Subtract the equations to get (x−y)(1−z)=0 and its cyclic analogues; the only triples are all 1 and all −2.'),(2,2.5,'The area identity ah=bk gives a+h−b−k=(a−b)(1−h/b)>0 for the stipulated obtuse angle.'),(3,1.5,'If two opposite-colour balls have equal weights, the required other weight must differ in both attributes from one of them.'),(4,3.5,'Writing the remaining digits as N gives 24N=6·10^k, hence 625 followed by zeros. The second equation 34N=d·10^k would require 17 to divide a leading digit.'),(5,3.5,'Expand the four squared side lengths into four terms t²+(1−t)², each between 1/2 and 1.'),(6,3.5,'Use the two parallel lines through A and B parallel to CM, where M is the midpoint of AB; C has equal distance from them.'),(7,2.5,'Either three integers have one residue modulo 3, or all three residues occur.'),(8,3.5,'If the midpoint is (x,y), the endpoints are (4x−2y,4x−2y) and (2y−2x,4y−4x). The length condition gives (2y−3x)²+(3y−4x)²=4.'),(9,3,'The partial sum is floor(n²/4); s+t and s−t have the same parity, so their rounding corrections cancel.')]:low(1970,n,d,why)
a(1970,10,4.5,'Number Theory',['Integer polynomials','Divisibility & GCD'],r'An integer-coefficient polynomial takes the value $5$ at four distinct integers. Prove that it cannot take the value $8$ at any integer.',r'If the four integers are $a,b,c,d$, the monic polynomial $(x-a)(x-b)(x-c)(x-d)$ divides $f(x)-5$ in $\mathbb Z[x]$, by repeated division by monic linear factors. If $f(k)=8$, then the product of the four distinct nonzero integers $k-a,k-b,k-c,k-d$ divides $3$. But four distinct nonzero integers have absolute product at least $1\cdot1\cdot2\cdot2=4$, impossible.','Repeated integral factorization converts four equal values into a divisibility obstruction; the distinctness bound on the four factors is essential.')
for n,d,why in [(1,2,'Power of E gives 3·5=1·(2r−1), so r=8.'),(2,2,'The product is 1+2/(xy), and xy≤1/4.'),(3,2,'Apply the cosine rule in ADC and BCD with equal adjacent side lengths and common CD; cosine decreases on (0,π).'),(4,3,'Subtract to get (a−1)(x−1)=0; a=1 works, otherwise x=1 forces a=−2.'),(5,2,'Every integer is congruent to 0 or 1 modulo 2, and the polynomial is odd at both residues.'),(6,3,'If 121 divided (n+1)²+11, then 11 would divide n+1, making the expression 11 modulo 121.'),(8,2.5,'Area decomposition gives five times the inradius, equal to 5r cos 36 degrees.'),(9,3.5,'Equality of elevation angles fixes the ratio of distances to the poles; the locus is an Apollonius circle, or the perpendicular bisector when the heights agree.')]:low(1971,n,d,why)
a(1971,7,4,'Number Theory',['Digits & bases','Divisibility & GCD'],r'A five-digit integer $n$ becomes the four-digit integer $m$ when its middle digit is removed. Find all $n$ for which $m$ divides $n$.',r'Write $n=1000A+100d+B$ and $m=100A+B$, where $10\le A\le99$, $0\le d\le9$, and $0\le B\le99$. Thus $n=10m+100d-9B$. The final term lies between $-891$ and $900$, while $m\ge1000$. If $m\mid n$, it follows that $100d=9B$. Hence $d$ is a multiple of 9; $d=9$ would give $B=100$, so $d=B=0$. Exactly the numbers $n=1000A$, $10\le A\le99$, work.','The key is to bound the correction to ten times the shortened number below one full divisor, forcing the quotient exactly.')
a(1971,10,4,'Combinatorics',['Graph theory','Logic & information','Extremal arguments'],r'Each of $n$ people initially knows one distinct fact. In a telephone call, the caller tells the recipient every fact they know, and receives no information. What is the fewest calls needed for everyone to learn all $n$ facts?',r'The answer is $2n-2$. One person can receive a call from everyone else and then call everyone else. For the lower bound, consider the first moment anyone knows all facts. The undirected graph of calls made so far must connect all $n$ people to that person: information cannot cross components. Thus at least $n-1$ calls have occurred. Every other person still lacks a fact and must subsequently be the recipient of a call, requiring another $n-1$ calls.','A sharp lower bound needs two separate phases, divided at the first fully informed person; a connectedness argument handles the first phase.')
for n,d,why in [(1,3.5,'The three centres form an equilateral triangle of side 2. Their common equidistant point gives the inner radius 2/√3−1 and enclosing radius 2/√3+1; a circle enclosing just one or two of the unit circles cannot also be tangent to the others.'),(2,1.5,'The least a_i has square no greater than each pairwise product, and hence no greater than their average.'),(3,2.5,'The base-b values factor as (b²+1)² and (b²+b+1)(b²−b+1).'),(4,3,'Reduce the trapezoid to a triangle having the two legs and the difference of the parallel bases as side lengths, then copy a parallel side.'),(6,1.5,'Choose (m,n)=(1,−1) or (−1,1) according to the sign of a−b.'),(8,3.5,'Pair each subset of promises with its complement. At most one member of each complementary pair can occur.')]:low(1972,n,d,why)
a(1972,5,4,'Number Theory',['Diophantine equations','Divisibility & GCD','Modular arithmetic'],r'Prove that $x^3+11^3=y^3$ has no solution in positive integers $x,y$.',r'Put $d=y-x>0$. Then $1331=d(3x^2+3xd+d^2)$, so $d\mid11^3$ and $d^3<11^3$. Therefore $d<11$, forcing $d=1$. But cubes are congruent to their bases modulo 3, so $y^3-x^3\equiv y-x=1\pmod3$, whereas $1331\equiv2\pmod3$.','Factoring the difference of cubes restricts the positive gap to a divisor below 11; a second modular obstruction then closes the proof.')
a(1972,7,4.5,'Algebra',['Equations & systems','Fractions & approximation'] if False else ['Equations & systems','Rationality & irrationality'],r'(a) Show that both roots of $x=(x^2+1)/198$ lie strictly between $1/198$ and $198-1/198$. (b) Deduce $\sqrt2<1.41\overline{421356}$. (c) Decide whether $\sqrt2<1.41421356$.',r'The roots are $99\pm70\sqrt2$, both positive. For either root, the equation gives $x>1/198$; since their sum is 198, each is also less than $198-1/198$. In particular, $99-70\sqrt2>1/198$, whence $\sqrt2<19601/13860=1.41\overline{421356}$. The finite decimal in (c) is smaller than $\sqrt2$: indeed $141421356^2=19999999932878736<2\cdot10^{16}$. Thus the asserted finite-decimal inequality is false.','The quadratic produces a precise rational upper bound; distinguishing a repeating decimal from its finite truncation requires an independent exact square comparison.')
a(1972,9,4,'Geometry',['Constructions & loci','Coordinates & vectors'],r'Four distinct lines form two pairs of parallel lines. Describe the locus of points for which the sum of the four perpendicular distances is a prescribed constant $C$.',r'First suppose the two directions differ. Let $u,v$ be signed perpendicular coordinates from the midlines of the pairs, and let $a,b>0$ be their half-separations. The distance sum is $2\max(|u|,a)+2\max(|v|,b)$. Hence the locus is empty for $C<2(a+b)$, the closed parallelogram $|u|\le a,|v|\le b$ for equality, and for $C>2(a+b)$ it is the boundary of the octagon $\max(|u|-a,0)+\max(|v|-b,0)\le C/2-a-b$. If all four lines are parallel, use a common signed normal coordinate with offsets $c_1<c_2<c_3<c_4$. The minimum sum is $c_4+c_3-c_2-c_1$; below it the locus is empty, at it the locus is the strip $c_2\le u\le c_3$, and above it the locus consists of the two parallel lines whose coordinates solve $\sum_i|u-c_i|=C$.','Signed distance coordinates turn the geometric locus into a piecewise linear level set; the minimum is a filled region, a case that must not be mistaken for only its boundary.')
a(1972,10,5,'Number Theory',['Sequences & recurrences','Divisibility & GCD','Extremal arguments'],r'What is the greatest possible length of a geometric progression of integers between $100$ and $1000$, inclusive, whose common ratio exceeds $1$?',r'The maximum is six, attained by $128,192,288,432,648,972$. Write the common ratio as $p/q>1$ in lowest terms. A progression of length $k$ has first term divisible by $q^{k-1}$ and last term divisible by $p^{k-1}$. If $k\ge7$, then $p^6\le1000$, so $p\le3$. Since $1\le q<p$, this forces $p/q\ge3/2$. Its last-to-first ratio would then be at least $(3/2)^6>10$, contrary to the allowed interval.','Integrality constrains both endpoints through powers of the reduced numerator and denominator; combining this with the interval ratio gives the sharp obstruction.')
for n,d,why in [(1,2.5,'The five short parts reduce to x<−1/2; largest integer −6; a mediant such as 17/37; 32·3125; and log_36(6)=1/2.'),(2,3,'Split at −3 and 1, solve each linear equation, and retain roots in their respective intervals.'),(3,2,'An odd twin-prime pair beyond 3 has middle term divisible by both 2 and 3.'),(4,3,'Vertices 2 and 5 force their triangles; successively vertices 4,1,3,6,7 force all remaining labels. There is exactly one labeling.'),(5,3,'Count each reciprocal 1/k in h(1)+...+h(n−1): its multiplicity is n−k.'),(7,3.5,'Use 1/n=1/(n+1)+1/[n(n+1)]. The consecutive sum telescopes to 1/i−1/(j+1); choose i=n−1 and j=n(n−1)−1.')]:low(1973,n,d,why)
a(1973,6,5.5,'Geometry',['Constructions & loci','Coordinates & vectors','Circles & tangency'],r'Points $A,B$ on a circle are distinct and not on one diameter. As $XY$ runs through diameters, let $P=AX\cap BY$ whenever the defining lines and their intersection exist. Determine the locus of $P$.',r'Normalize the circle to the complex unit circle and write $a,b,x,p$ for the points, with $Y=-x$. A line joining unit points $u,v$ has equation $z+uv\bar z=u+v$. Thus $p+ax\bar p=a+x$ and $p-bx\bar p=b-x$. Dividing by $a,b$ respectively and adding yields $x=[(a+b)p-2ab]/(b-a)$. Since $|x|=1$, the locus lies on $|p-2ab/(a+b)|=|b-a|/|a+b|$. Its centre is the intersection of the tangents at $A,B$, and it passes through both. Conversely, a point on this circle determines a unit $x$ by the displayed formula; substituting the circle equation verifies both line equations. Omit the two points $p=(3ab-a^2)/(a+b)$ and $p=(3ab-b^2)/(a+b)$, corresponding respectively to $X=A$ and $Y=B$, where a defining chord has coincident endpoints. All other points occur; in particular $A$ and $B$ themselves do occur.','The moving diameter creates a nonstandard circle centred at the intersection of two tangents. A complex line equation establishes both the locus and its converse, including excluded endpoints.')
low(1974,1,2.5,'Substitute the two powers for the first identity; pair consecutive squares or induct for the alternating-square identity.')
low(1974,2,3.5,'The angles have tangents 1/3,1/2,1, so the tangent-addition identity gives the result.')
low(1974,3,3.5,'The coefficient is at most a₀(a₁+...+aₙ)≤f(1)²/4, which is stronger than required.')
a(1974,4,4,'Algebra',['Inequalities','Extremal arguments'],r'For $n$ real numbers $0\le x_i\le1$, determine the maximum of $\sum_{1\le i<j\le n}|x_i-x_j|$.',r'Order the numbers increasingly. The sum becomes $\sum_{i=1}^n(2i-n-1)x_i$. Every negative coefficient is best paired with 0 and every positive coefficient with 1; the possible central zero coefficient makes no difference. Thus the maximum is $\lfloor n^2/4\rfloor$, attained by taking $\lfloor n/2\rfloor$ zeros and the remaining entries ones.','Sorting exposes the signed linear coefficients and identifies the correct extremal configuration; the final count depends on the parity of n.')
a(1974,5,4.5,'Geometry',['Coordinates & vectors','Concurrency & collinearity','Circles & tangency'],r'A circle has diameter $AB$. For another point $X$ on the circle, let $Y$ be the intersection of $BX$ with the tangent at $A$, and $Z$ the intersection of $AX$ with the tangent at $B$. Prove that $YZ$, $AB$, and the tangent at $X$ are concurrent or parallel.',r'Scale to $A=(-1,0)$, $B=(1,0)$, and $X=(u,v)$ with $u^2+v^2=1$ and $v\ne0$. Then $Y=(-1,2v/(1-u))$ and $Z=(1,2v/(1+u))$. Their line is $ux+vy/2=1$, while the tangent at $X$ is $ux+vy=1$. If $u\ne0$, both meet $AB$ at $(1/u,0)$. If $u=0$, both are horizontal and parallel to $AB$.','The coordinate proof requires finding the secant-tangent intersections and keeping the exceptional parallel case when the common intercept goes to infinity.')
a(1974,6,4,'Number Theory',['Diophantine equations','Modular arithmetic'],r'Using any number of $8$-cent and $15$-cent stamps, what is the largest integer amount of postage that cannot be formed?',r'The answer is $97$. If $97=8a+15b$ with nonnegative integers $a,b$, reduction modulo 8 gives $b\equiv7\pmod8$, so $15b\ge105$, impossible. For any $N\ge98$, choose $b\in\{0,1,\ldots,7\}$ with $15b\equiv N\pmod8$. Then $N-15b\ge-7$ and is divisible by 8, hence is nonnegative. This gives the desired representation.','One residue choice proves representability uniformly above the sharp gap; verifying only a few examples would not establish the threshold.')
hold(1974,7,'Bus timetable question is not published yet: original says only that each 12-mile circuit takes 20 minutes, without explicitly fixing speed along the route. Under the conventional common constant-speed interpretation, the supremum waiting-plus-travel time on the circle is (5/3) times the piecewise functions 12+x (1<x≤3),18−x (3≤x≤6),6+x (6≤x≤9),24−x (9≤x<11), giving w(2)=w(4)=70/3 and maximum25 at x=3,9. The shared stem, the junction endpoints, and the unstated speed assumption need source clarification before inclusion.')
for n,d,why in [(1,1,'Numerator and denominator are 8 and 27 times the same sum of cubes; the cube root is 2/3.'),(2,3,'Subtract consecutive partial-sum equations to get a_n=(n−1)a_(n−1)/(n+1), hence a_n=1/[n(n+1)].'),(3,2,'The floor pair must be one of (±2,0),(0,±2), giving four half-open unit squares.'),(4,3.5,'Writing integer part a and decimal part d gives a²=d(a+d). Then d=a(√5−1)/2<1 forces a=1.'),(5,3,'The two opposite arcs between consecutive arc-midpoints sum to a semicircle, so the intersecting chords are perpendicular.'),(6,3.5,'Across all rotations the total correct placements is 15. If the original rotation has none, one of the other 14 has at least two. The permutation i↦2i modulo15 has one match under every rotation.'),(8,3.5,'If P is nonconstant, its range is infinite and P(t)−t^k vanishes on that range, forcing P(x)=x^k. Constants satisfy c=c^k.')]:low(1975,n,d,why)
a(1975,7,4,'Algebra',['Functions & graphs','Trigonometry','Rationality & irrationality'],r'Is the function $f(x)=\sin(x^2)$ periodic on the real line? Prove your answer.',r'It is not. Suppose $p>0$ were a period. Since $f(0)=0$, we have $p^2=k\pi$ for a positive integer $k$. Also $f(\sqrt\pi+p)=f(\sqrt\pi)=0$, so $k+1+2\sqrt k$ is an integer, making $2\sqrt k$ an integer. Applying the same argument at $\sqrt{2\pi}$ makes $2\sqrt{2k}$ an integer. The ratio of these two nonzero integers would be $\sqrt2$, a contradiction.','The irregular spacing of zeros is not by itself a proof; choosing three particular zeros forces two incompatible rationality conditions on a hypothetical period.')
low(1976,1,3.5,'Weigh two pairs, then compare the members of the heavier pair. The pair containing the largest weight always outweighs the other: the only nontrivial case is r³+1>r²+r.')
a(1976,2,4,'Algebra',['Sequences & recurrences','Induction'],r'Let $a_0=1$, $a_1=2$, and $n(n+1)a_{n+1}=n(n-1)a_n-(n-2)a_{n-1}$ for $n\ge1$. Find $\sum_{j=0}^{50}a_j/a_{j+1}$.',r'The cases $n=1,2$ give $a_2=1/2$, $a_3=1/6$. If $a_n=1/n!$ and $a_{n-1}=1/(n-1)!$ for $n\ge3$, then the right side is $[n-1-(n-2)]/(n-1)!=1/(n-1)!$, so $a_{n+1}=1/(n+1)!$. Therefore the requested sum is $1/2+4+\sum_{j=2}^{50}(j+1)=2655/2$.','Recognizing the factorial pattern after the two exceptional initial terms turns a second-order recurrence into a simple sum, with the initial exceptions needing separate treatment.')
a(1976,3,4.5,'Number Theory',['Divisibility & GCD','Diophantine equations'],r'Two grade-seven students join a round-robin chess tournament with some grade-eight students. A win earns $1$, a draw $1/2$, and a loss $0$. The younger students score $8$ points in total, and every older student has the same score. How many older students can there be?',r'Let there be $m$ older students, each scoring $s$. The total points equal the number of games, so $ms=(m+2)(m+1)/2-8$, or $2s=m+3-14/m$. Since $2s$ is integral, $m\mid14$. The younger pair can score at most $2m+1$, which excludes $m=1,2$, leaving $m=7,14$. Both occur. With $m=7$, make every game a draw. With $m=14$, let older students draw against one another, beat one younger student, and draw against the other; the younger pair’s mutual game contributes the remaining one point.','The score identity creates a divisor restriction, but the count is not unique; feasibility constructions are needed to distinguish algebraic possibilities from actual tournaments.')
low(1976,4,3,'The printed relation is AC/CB=QC/CP, so CP is a fixed multiple of CQ. With ordinary unoriented lengths, both homotheties about C occur; their images of the original circle give the locus.')
a(1976,5,4.5,'Number Theory',['Divisibility & GCD','Sequences & recurrences','Parity'],r'Prove that a positive integer can be written as a sum of at least two consecutive positive integers if and only if it is not a power of two.',r'If $n=a+(a+1)+\cdots+(a+\ell-1)$ with $a\ge1$, $\ell\ge2$, then $2n=\ell(2a+\ell-1)$. The two factors have opposite parity, and the odd one exceeds 1, so $n$ is not a power of two. Conversely write $n=2^k m$ with odd $m>1$. If $m<2^{k+1}$, use $m$ consecutive terms centred at $2^k$; the first is $2^k-(m-1)/2\ge1$. If $m>2^{k+1}$, use $2^{k+1}$ consecutive terms centred at $m/2$; the first is $(m-2^{k+1}+1)/2\ge1$. Both sums equal $n$.','The factorization of twice the sum gives the obstruction; constructing a positive run requires switching between odd and even lengths according to the size of the odd part.')
a(1976,6,4.5,'Geometry',['Solid geometry','Coordinates & vectors'],r'Four points $A,B,C,D$ in space satisfy $\angle ABC=\angle BCD=\angle CDA=\angle DAB=90^\circ$. Prove they are coplanar.',r'Take $A$ as origin and write $B=b$, $D=d$, $C=c$. The four right angles give $b\cdot d=0$, $b\cdot c=|b|^2$, $d\cdot c=|d|^2$, and $(b-c)\cdot(d-c)=0$. The last equation gives $|c|^2=|b|^2+|d|^2$. Write $c=b+d+w$, where the first three equations ensure that $w$ is orthogonal to both $b$ and $d$. Then $|c|^2=|b|^2+|d|^2+|w|^2$, so $w=0$. Thus $C=B+D$ in these coordinates, proving coplanarity.','Three perpendicularity conditions isolate a possible out-of-plane component; the fourth forces its squared length to vanish.')
low(1976,7,3,'After dividing by x−y, symmetry makes the quotient antisymmetric. It vanishes at x=y and is divisible by x−y again.')
a(1976,8,5.5,'Combinatorics',['Graph theory','Colouring','Parity'],r'Colour every edge joining nine points red or blue. Suppose no triangle has all three edges blue. Prove that some four points have all six joining edges red.',r'If a vertex has at least four blue neighbours, all edges between those neighbours are red, giving the result. Otherwise all blue degrees are at most 3. The sum of nine odd degrees cannot be even, so some vertex has even blue degree, at most 2. It therefore has at least six red neighbours. Among any six vertices there is a monochromatic triangle: from one vertex, at least three incident edges have one colour, and either an edge among their endpoints shares that colour or those endpoints form a triangle of the other colour. Since blue triangles are forbidden, the six red neighbours contain a red triangle. Adding the chosen vertex gives the required red four-set.','The sharp nine-vertex bound needs a parity improvement to the degree bound followed by the six-vertex Ramsey argument.')
for n,d,why in [(1,3,'The equation becomes (2b+1)²−4(2a+1)²=−3; factor the two integers of product −3 to force a=0.'),(2,3.5,'The sine rule bounds sin(angle OPA) by OA/OP, with equality when AP is perpendicular to OA. The relevant angle is acute.'),(4,3.5,'Reduce the polynomial product modulo2; the polynomial ring over a field has no zero divisors. Both factors cannot be entirely even, since the product is not entirely divisible by4.'),(5,3.5,'Unroll the cone into a sector of angle120 degrees. The shortest path is its chord, whose distance from the apex is 3cos60=3/2.'),(6,3,'The interval 1<u_n≤1+u is preserved because 1/(1+u)+u>1 and 1/u_n+u<1+u.')]:low(1977,n,d,why)
a(1977,3,4,'Number Theory',['Digits & bases','Squares & powers','Divisibility & GCD'],r'Find the smallest base $b$ in which the numeral $777$ represents a fourth power of an integer.',r'The represented value is $7(b^2+b+1)$. If this equals $a^4$, primality of 7 gives $7\mid a$, so $a\ge7$. Thus $b^2+b+1\ge7^3=343$. Since $17^2+17+1=307$ and $18^2+18+1=343$, the smallest possible base is $18$, and it works because $7\cdot343=7^4$.','Divisibility of a fourth power forces its root to be a multiple of7, giving a sharp size lower bound that is exactly attained.')
a(1977,7,6.5,'Combinatorics',['Graph theory','Bijections','Combinatorial geometry'],r'A rectangular grid has $m$ by $n$ unit cells. A pedestrian travels along grid edges from the southwest corner to the northeast corner without visiting any vertex twice. Prove that there are at most $2^{mn}$ possible routes.',r'Fix one boundary route $B$ between the two corners. For any admissible route $P$, take the symmetric difference $E=P\triangle B$ of their edge sets. Every vertex has even degree in $E$. Such an edge set uniquely determines a subset of the $mn$ cells: colour the exterior white, and change colour whenever a path between adjacent faces crosses an edge of $E$. This is consistent because every vertex has even degree; equivalently, any closed dual walk crosses $E$ an even number of times. The black cells have boundary exactly $E$. Conversely their boundary recovers $E$, then $P=E\triangle B$. An edge set of a simple route determines that route uniquely from its starting corner. Thus the routes inject into the $2^{mn}$ subsets of cells.','The useful encoding is not a sequence of local turns but the mod-two region bounded by the route and a fixed boundary path; consistency and injectivity both require proof.')
low(1978,1,2,'Modulo4 leaves units 2,3,6,7 among numbers with tens digit7; modulo5 leaves only6.')
a(1978,2,4.5,'Number Theory',['Diophantine equations','Valuations'],r'Find all positive integer pairs $(a,b)$ satisfying $2a^2=3b^3$.',r'For every prime $p\ne2,3$, the equality $2v_p(a)=3v_p(b)$ makes the exponents in $a,b$ multiples of3 and2 respectively. At2, $1+2v_2(a)=3v_2(b)$ forces $v_2(b)$ odd, say $2r+1$, and $v_2(a)=3r+1$. At3, $2v_3(a)=1+3v_3(b)$ similarly gives $v_3(b)=2s+1$ and $v_3(a)=3s+2$. Combining these exponents gives exactly $b=6t^2$ and $a=18t^3$ for positive integers $t$, and direct substitution verifies every pair.','A complete parametrization needs separate exponent balances at2 and3, alongside the ordinary primes.')
a(1978,3,4,'Algebra',['Equations & systems','Inequalities'],r'What is the largest possible real $z$ if real $x,y$ satisfy $x+y+z=5$ and $xy+yz+zx=3$?',r'For fixed $z$, the other two numbers must have sum $5-z$ and product $z^2-5z+3$. They are real exactly when the discriminant $(5-z)^2-4(z^2-5z+3)=13+10z-3z^2$ is nonnegative. Therefore $z\le(5+2\sqrt{22})/3$. This endpoint is attainable by taking $x=y=(5-z)/2$.','Eliminating the other variables leaves a discriminant condition; checking its endpoint also proves attainability of the maximum.')
a(1978,4,4.5,'Geometry',['Area & dissection','Coordinates & vectors'],r'In a convex quadrilateral $ABCD$, the lines $AD$ and $BC$ meet at $E$. If $G,H$ are the midpoints of $AC,BD$, find the ratio $[EGH]/[ABCD]$.',r'Take $E$ as the origin and write $A=au$, $D=du$, $B=bv$, $C=cv$ for independent vectors $u,v$. Since $E$ lies outside both side segments, orient the rays so $a,b,c,d$ are positive. The quadrilateral area is $|ab-cd|\,|\det(u,v)|/2$. Its midpoint vectors are $G=(au+cv)/2$, $H=(du+bv)/2$, so the triangle area is $|ab-cd|\,|\det(u,v)|/8$. The ratio is therefore $1/4$.','Affine coordinates at the external intersection cause the same determinant factor to appear in both areas, revealing an invariant ratio.')
a(1978,5,5,'Combinatorics',['Games & strategies','Parity'],r'Two players alternately fill empty cells of a $3\times3$ board, choosing a black or white counter independently at every move. When full, Eve scores one point for each row, column or main diagonal having an even number of black counters, and Odette scores one for each such line having an odd number. Can the score be $4$–$4$? Give a winning strategy for either player moving first.',r'A tie is possible: put a black counter only in the centre. Exactly the four lines through the centre have odd black count. For a winning strategy, the first player claims the centre: Eve uses black, Odette white. After every opponent move, play in the cell opposite it through the centre, with the opposite colour. All four lines through the centre then contain one black off-centre counter; their parity is therefore even for Eve and odd for Odette. Of each pair of opposite outer rows, exactly one has even black count, because their combined count is3; the same holds for the outer columns. The first player thus scores six points.','The parity objective requires choosing the centre colour opposite to the player’s desired parity, then an antipodal response ensures four central points and two additional outer points.')
a(1978,6,5,'Algebra',['Equations & systems','Functions & graphs'],r'Describe and sketch the real curve $x^3+xy+y^3=3$.',r'Use rotated coordinates $u=x+y$, $v=x-y$. The equation becomes $(3u-1)v^2=(2-u)(u^2+3u+6)$. Since the quadratic factor is always positive, real points occur exactly for $1/3<u\le2$, and are parametrized by $v=\pm\sqrt{(2-u)(u^2+3u+6)/(3u-1)}$, $x=(u+v)/2$, $y=(u-v)/2$. The branches join at $(1,1)$ and are reflections in $x=y$. As $u$ decreases to $1/3$, $|v|$ tends to infinity, giving the asymptote $x+y=1/3$. The curve crosses the axes at $(\sqrt[3]3,0)$ and $(0,\sqrt[3]3)$. These formulas specify the two symmetric branches and give an exact parametrization for the sketch.','The rotation separates a squared difference from a sum variable, turning an opaque cubic curve into two explicitly controlled branches with a non-obvious asymptote.')
low(1979,1,2,'The geometric product is ab and the arithmetic product exceeds it by 2(a−b)²/9.')
a(1979,2,4.5,'Geometry',['Solid geometry','Geometric inequalities'],r'Prove that the sum of the six interior dihedral angles of a tetrahedron is not the same for all tetrahedra.',r'Consider tetrahedra with a fixed equilateral base and an apex at height $h>0$ above its centre. At the regular tetrahedron height, all six dihedral angles are $\arccos(1/3)$, so their sum is strictly less than $3\pi$. As $h$ tends to zero, each of the three base-edge interior dihedral angles tends to0, while each of the other three tends to $\pi$. Thus the sum tends to $3\pi$. If the sum were constant throughout this family, its limit would equal its regular-tetrahedron value, a contradiction. All tetrahedra in the family with $h>0$ are nondegenerate.','A varying family avoids difficult exact counterexample arithmetic: the limiting flattening changes the sum, and continuity makes the comparison rigorous for nondegenerate tetrahedra.')
a(1979,3,6.5,'Number Theory',['Divisibility & GCD','Inequalities','Induction'],r'If $1\le a<b<c<d<e$ are integers, prove $1/\operatorname{lcm}(a,b)+1/\operatorname{lcm}(b,c)+1/\operatorname{lcm}(c,d)+1/\operatorname{lcm}(d,e)\le15/16$.',r'We prove the stronger statement that a chain of $k$ adjacent pairs starting at $a$ has sum at most $(1-2^{-k})/a$. The case $k=0$ is trivial. Let the next integer be $b$. If $b\ge2a$, the first term is at most $1/b$, and induction bounds the rest by $(1-2^{-(k-1)})/b$; together these are at most $(1-2^{-k})/a$. If $a<b<2a$, use $\gcd(a,b)\le b-a$, so $1/\operatorname{lcm}(a,b)\le1/a-1/b$. Adding the inductive bound gives $1/a-1/(2^{k-1}b)<(1-2^{-k})/a$. Take $k=4$ and $a\ge1$. Equality occurs for $1,2,4,8,16$.','The sharp constant emerges only after strengthening the statement to arbitrary chain length and splitting according to whether the next integer at least doubles.')
a(1979,4,4.5,'Geometry',['Constructions & loci','Trigonometry'],r'A rabbit runs along the wall of a circular arena. A dog starts at its centre and runs at the same speed, always remaining on the radius through the rabbit. Show that it catches the rabbit after the rabbit travels one quarter of the circumference.',r'Let the arena radius be $R$ and let $\theta$ be the angle the rabbit has travelled from its starting radius. Consider the dog path $r=R\sin\theta$, $0\le\theta\le\pi/2$. In Cartesian coordinates this is the circle $x^2+(y-R/2)^2=(R/2)^2$, starting at the origin. Its arc from the origin to angle $\theta$ has central angle $2\theta$ and length $R\theta$, exactly the rabbit’s travelled distance. It stays on the rabbit’s radius and inside the arena until $\theta=\pi/2$, when $r=R$. Thus this is the prescribed equal-speed pursuit path, and capture occurs after one quarter turn.','The useful insight is a small circle through the arena centre; its double-angle arc relation proves the equal-speed condition without solving a differential equation.')
low(1979,5,3.5,'The first counts are4,12,36,100: from108 nonbacktracking four-step walks remove eight unit-square loops. Nonbacktracking gives the upper bound; the 2^n north/east walks plus at least one other give the strict lower bound.')
low(1980,1,2,'Divisibility by8 forces b=2; divisibility by9 then forces a=3.')
a(1980,2,4.5,'Combinatorics',['Algorithms & constructions','Permutations & arrangements'],r'Distinct numbered cards are placed in a rectangular array. Sort each row increasingly from left to right, then sort each column increasingly from top to bottom. Must every row still increase from left to right?',r'Yes. Consider any two adjacent columns just after the row sorting. Their entries can be paired as $a_i<b_i$. Let $a_{(k)},b_{(k)}$ be their respective $k$th smallest entries. Among the $k$ entries $b_i\le b_{(k)}$, their paired $a_i$ are all strictly smaller than $b_{(k)}$. Hence $a_{(k)}<b_{(k)}$. This holds for every $k$ and every adjacent column pair, so sorting the columns preserves increasing rows.','The second sorting step destroys the original pair positions; comparing order statistics through the original pairings proves the claimed preservation.')
a(1980,3,4.5,'Geometry',['Triangle centres','Geometric inequalities','Trigonometry'],r'Among triangles with a fixed angle $A$ and fixed inradius $r$, which has least perimeter?',r'If the other angles are $B,C$, the semiperimeter is $r(\cot(A/2)+\cot(B/2)+\cot(C/2))$, by the tangent lengths from each vertex. Put $u=B/2$, $v=C/2$; their sum is fixed. Now $\cot u+\cot v=\sin(u+v)/(\sin u\sin v)$, and $\sin u\sin v=[\cos(u-v)-\cos(u+v)]/2$ is largest exactly when $u=v$. Thus the least perimeter occurs uniquely when $B=C$, namely for the isosceles triangle with the specified angle as its vertex angle.','The inradius constraint is best converted to tangent lengths; optimizing the remaining cotangent sum identifies the equality configuration.')
a(1980,4,4,'Combinatorics',['Probability','Recurrences & generating functions'],r'A fair coin gives one point for heads and two points for tails. Toss it repeatedly. Prove that the probability the running total ever equals a given nonnegative integer $n$ is $\frac13(2+(-\frac12)^n)$.',r'Write the probability as $p_n$. Then $p_0=1$, $p_1=1/2$, and conditioning on the first toss gives $p_n=(p_{n-1}+p_{n-2})/2$ for $n\ge2$. The proposed expression has these initial values and satisfies the recurrence, since both $1$ and $-1/2$ solve $2t^2=t+1$. Induction proves the formula.','The event is hitting a running total rather than stopping after a fixed number of tosses; conditioning gives a second-order recurrence with an alternating correction.')
a(1980,5,5.5,'Geometry',['Solid geometry','Coordinates & vectors','Constructions & loci'],r'Every nondegenerate section of a parallelepiped parallel to a face has the same perimeter as that face. Does any other polyhedron have this property for every face direction?',r'Yes: a regular octahedron. Take $|x|+|y|+|z|\le1$. One face is in $x+y+z=1$, an equilateral triangle of perimeter $3\sqrt2$. For $-1<t<1$, the section $x+y+z=t$ is a hexagon whose vertices are the permutations of $((1+t)/2,-(1-t)/2,0)$. Its three alternating side lengths are $(1+t)/\sqrt2$ and its other three are $(1-t)/\sqrt2$, giving total $3\sqrt2$. At $t=\pm1$ the section is the triangular face with the same perimeter. Changing coordinate signs handles every other face direction. The octahedron is not a parallelepiped.','A valid counterexample must work for all face directions. The octahedron’s parallel slices change shape but have alternating edge lengths whose sum stays fixed.')
ids={p['id'] for p in new};data=[p for p in data if p['id'] not in ids]+new
